# calculate the median
def median(nums):
    nums.sort()
    if len(nums) % 2 == 0:
        return (nums[len(nums)//2-1] + nums[len(nums)//2]) / 2
    else:
        return nums[len(nums)//2]

# calculate the mode
def mode(nums):
    nums.sort()
    max_count = 1
    mode = nums[0]
    current_count = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i-1]: 
            current_count += 1
            if current_count > max_count:
                max_count = current_count 
                mode = nums[i]
        else:
            current_count = 1

    return mode

