class Stack:
    def __init__(self):
        self.items = []
        self. minvalue = None

    def push(self, item):
        self.items.append(item)
        if self.minvalue is None or item < self.minvalue:
            self.minvalue = item

    def pop(self):
        item = self.items.pop()
        if self.minvalue == item:
            if len(self.items) > 0:
                self.minvalue = min(self.items)
            else:
                self.minvalue = None
        return item
